frame.store("_a_clause_of_its_own", { let __default_2817 = Value::None; let __signature_2815 = Signature { name: "_a_clause_of_its_own".into(), positional: vec!["rest".into(),"clauses".into()], positional_only: 0, defaults: vec![__default_2817], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2818 = Value::dict(); __attrs_2818.dict_set(Value::from("__doc__"), Value::from("True when the rest of a line that opens with a thank-you says something of its own.\n\n    A thank-you at the front of a line is a wrapper round what follows it, and what follows it\n    is often the point: \"cheers, im skint till friday\" is news about the week, and read as a\n    thank-you it was answered with the answer to the turn before, all over again. The\n    thank-you does hold what comes after it when that is short (\"thanks, it worked\"), opens\n    with what the thanks is about (\"thanks, that explains the boiler\"), is agreement (\"thanks,\n    that worked a treat\"), or says things are better (\"thanks, i feel much better now\"). A\n    clause of four words or more that does none of those is the line, and the line needs an\n    answer.\n    "))?; __attrs_2818.dict_set(Value::from("__defaults__"), Value::tuple(__signature_2815.defaults.clone()))?; let __kwdefaults_2819 = Value::dict(); __attrs_2818.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2814 = Frame::module(frame.globals.clone()); let mut __function_2816 = NativeFunction::qualified_with_origin("_a_clause_of_its_own".into(), "_a_clause_of_its_own".into(), "bot.understanding.kinds".into(), __attrs_2818, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/kinds.py", first: 3857, last: 3896, qualname: "_a_clause_of_its_own" }, closure: __closure_2814.clone(), freevars: vec![] }, move |rt, args| __py_95::_a_clause_of_its_own(rt, __closure_2814.clone(), &__signature_2815, args)); __function_2816 })?;
frame.store("_a_step_done", { let __signature_2821 = Signature { name: "_a_step_done".into(), positional: vec!["rest".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2823 = Value::dict(); __attrs_2823.dict_set(Value::from("__doc__"), Value::from("True when the rest of the line reports doing a step of the advice, and nothing went wrong.\n\n    \"thanks, i cleared the cache\" and \"cheers, i restarted the router\" are the person saying they\n    did what the bot suggested. The step is named as a thing being acted on (\"the\", \"my\", \"it\"),\n    so a line about the person's own day keeps its own answer: \"thanks, i booked a table for\n    friday\" is still news, and \"thanks, i tried the new place on saturday\" is a thing they did\n    rather than a report back. A step that went wrong is the news, not the thank-you.\n    "))?; __attrs_2823.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_2824 = Value::dict(); __attrs_2823.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2820 = Frame::module(frame.globals.clone()); let mut __function_2822 = NativeFunction::qualified_with_origin("_a_step_done".into(), "_a_step_done".into(), "bot.understanding.kinds".into(), __attrs_2823, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/kinds.py", first: 3899, last: 3923, qualname: "_a_step_done" }, closure: __closure_2820.clone(), freevars: vec![] }, move |rt, args| __py_96::_a_step_done(rt, __closure_2820.clone(), &__signature_2821, args)); __function_2822 })?;
